 if(x.best&&sel&&x.best.id!==sel.id&&sel.profit!==null)html+='<p class="b-tradeoff-line">“'+esc(x.best.name)+'” te da <b>'+money(x.best.profit-sel.profit)+'</b> más en el mismo tiempo.</p>';
