 items=items.filter(x=>{const s=x.type==='activity'?x.status:x.fieldMeta?.price?.status||'unknown';return(f.status==='all'||f.status==='known'&&x.price!==null||f.status==='unknown'&&x.price===null&&x.type!=='activity'||s===f.status)&&(f.maxPrice===null||x.price!==null&&x.price<=f.maxPrice);});
 items.sort((a,b)=>f.sort==='name'?((a.brand||'')+' '+a.name).localeCompare((b.brand||'')+' '+b.name,'fr'):(a.price===null&&b.price===null?0:a.price===null?1:b.price===null?-1:(f.sort==='price-up'?a.price-b.price:b.price-a.price))||a.name.localeCompare(b.name,'fr'));
 $('catalogue-count').textContent=items.length+' resultado'+(E.plural(items.length)?'s':'')+(f.maxPrice!==null?' · precios desconocidos excluidos':'');
 const chips=[['query',f.query],['type',f.type!=='all'?labels[f.type]:null],['status',f.status!=='all'?$('catalogue-status').selectedOptions[0]?.textContent:null],['maxPrice',f.maxPrice!==null?'≤ '+money(f.maxPrice):null],['favoritesOnly',f.favoritesOnly?'Favoritos':null]].filter(x=>x[1]);
 $('catalogue-filter-chips').innerHTML=chips.map(([k,v])=>'<button class="calc-chip" data-remove-filter="'+k+'">'+esc(v)+' ×</button>').join('')+(chips.length?'<button class="calc-text-button" data-reset-filters="1">Restablecer todo</button>':'');
